import * as THREE from 'three/webgpu';
import {
  MeshStandardNodeMaterial,
  texture,
  mul,
  add,
  positionWorld,
  vec3,
} from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  // -----------------------------------------------------------------
  // Load textures (synchronous via ctx.textureLoader)
  // -----------------------------------------------------------------
  const colorTex = ctx.textureLoader.load(config.imageUrl);
  const depthTex = ctx.textureLoader.load(config.depthMapUrl);

  // -----------------------------------------------------------------
  // Geometry & Node‑Based Material
  // -----------------------------------------------------------------
  const geometry = new THREE.PlaneGeometry(1, 1, 64, 64);

  const material = new MeshStandardNodeMaterial();
  material.colorNode = texture(colorTex);
  // subtle displacement using depth map (parallax‑like effect)
  material.displacementNode = mul(texture(depthTex).r, 0.05);
  // machined‑metal look
  material.metalness = 0.45;
  material.roughness = 0.55;
  material.clearcoat = 0.2;
  material.clearcoatRoughness = 0.2;
  material.side = THREE.DoubleSide;
  material.transparent = true;

  const plane = new THREE.Mesh(geometry, material);
  plane.castShadow = false;
  plane.receiveShadow = false;

  // -----------------------------------------------------------------
  // Root object – placed according to spec
  // -----------------------------------------------------------------
  const root = new THREE.Object3D();
  root.position.set(
    config.position?.[0] ?? -1.25,
    config.position?.[1] ?? 1.6,
    config.position?.[2] ?? 0
  );
  root.rotation.set(
    config.rotation?.[0] ?? 0,
    config.rotation?.[1] ?? 0,
    config.rotation?.[2] ?? 0
  );
  root.scale.set(
    config.scale?.[0] ?? 1,
    config.scale?.[1] ?? 1,
    config.scale?.[2] ?? 1
  );
  root.add(plane);

  // -----------------------------------------------------------------
  // Interaction handling (hover rise‑in, click emit)
  // -----------------------------------------------------------------
  const originalY = root.position.y;
  const timelines = [];

  const startHover = () => {
    const tl = gsap.to(root.position, {
      y: originalY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(tl);
  };

  const endHover = () => {
    const tl = gsap.to(root.position, {
      y: originalY,
      duration: 0.4,
      ease: 'power3.inOut',
    });
    timelines.push(tl);
  };

  const handleClick = () => {
    // emit selection event
    if (ctx.emit) ctx.emit('hub-features.select');

    // data binding: checkout URL navigation
    if (ctx.trpc && ctx.trpc['checkout.begin']) {
      ctx.trpc['checkout.begin']().then((resp) => {
        if (resp?.checkoutUrl && ctx.navigate) {
          ctx.navigate(resp.checkoutUrl);
        }
      });
    }
  };

  // expose handlers – external system will call them
  root.userData.handlers = {
    hover: startHover,
    hoverout: endHover,
    click: handleClick,
  };

  // -----------------------------------------------------------------
  // Apply any cinematic primitives listed in config (none here)
  // -----------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives?.[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    });
  }

  // -----------------------------------------------------------------
  // Cleanup routine
  // -----------------------------------------------------------------
  root.userData.cleanup = () => {
    // dispose geometries & materials
    geometry.dispose();
    material.dispose();

    // dispose textures if they are owned uniquely
    if (colorTex && colorTex.dispose) colorTex.dispose();
    if (depthTex && depthTex.dispose) depthTex.dispose();

    // kill GSAP timelines
    timelines.forEach((t) => t.kill());
    timelines.length = 0;

    // remove from parent if still attached
    if (root.parent) root.parent.remove(root);
  };

  return root;
}
